/* --- ./supabase-single-client.js --- */
(function () {
  'use strict';

  const config = window.H38_BUSINESS_OFFICE_SUPABASE || {};
  const sdk = window.supabase;
  if (!config.enabled || !sdk || typeof sdk.createClient !== 'function') return;
  if (window.H38_SUPABASE_SHARED_CLIENT?.enabled) return;

  const originalCreateClient = sdk.createClient.bind(sdk);
  let sharedClient = null;
  let createdCount = 0;
  let reusedCount = 0;

  function isOfficeClient(url, key, options) {
    const auth = options && options.auth || {};
    return String(url || '') === String(config.url || '') &&
      String(key || '') === String(config.publishableKey || '') &&
      auth.persistSession !== false;
  }

  sdk.createClient = function (url, key, options) {
    if (!isOfficeClient(url, key, options)) return originalCreateClient(url, key, options);
    if (sharedClient) {
      reusedCount += 1;
      return sharedClient;
    }
    const requested = options || {};
    const requestedAuth = requested.auth || {};
    sharedClient = originalCreateClient(url, key, {
      ...requested,
      auth: {
        ...requestedAuth,
        persistSession: true,
        autoRefreshToken: true,
        detectSessionInUrl: true,
        // Supabase admin invitation links do not support PKCE because the
        // browser requesting an invite is commonly different from the browser
        // accepting it. The Business Office uses one shared implicit-flow
        // client so invite, recovery, and existing password sessions resolve
        // through the same persisted session and exact-email membership claim.
        flowType: 'implicit'
      }
    });
    createdCount += 1;
    return sharedClient;
  };

  window.H38_SUPABASE_SHARED_CLIENT = Object.freeze({
    enabled: true,
    build: '20260808-2308-invite-auth',
    authFlow: 'implicit-invite-compatible',
    get: function () { return sharedClient; },
    ensure: function () {
      return sharedClient || sdk.createClient(config.url, config.publishableKey, {
        auth: {
          persistSession: true,
          autoRefreshToken: true,
          detectSessionInUrl: true,
          flowType: 'implicit'
        },
        global: { headers: { 'x-client-info': 'h38-business-office-shared-client' } }
      });
    },
    stats: function () { return { createdCount, reusedCount, hasClient: Boolean(sharedClient) }; },
    rotatingRefreshOwner: 'single-client'
  });
})();
;

/* --- ./supabase-auth.js --- */
(function () {
  'use strict';

  const config = window.H38_BUSINESS_OFFICE_SUPABASE || {};
  const LegacyBridge = window.H38Bridge;
  const runtime = {
    client: null,
    bridge: null,
    session: null,
    user: null,
    memberships: [],
    activeMemberships: [],
    selectedMembership: null,
    recovery: false,
    subscription: null
  };

  const EMPTY_COLLECTIONS = [
    'users','roles','settings','quickActions','providers','customers','contacts','properties','requests','jobs',
    'workOrders','tasks','scheduleEvents','timeEntries','jobNotes','quotes','measurements','measurementPoints',
    'priceBook','inventoryTransactions','materialRequests','assets','assignments','maintenance','inspections',
    'vehicles','usageLogs','invoices','invoiceLines','payments','expenses','documents','attachments','conversations',
    'messages','emailThreads','emailMessages','smsThreads','smsMessages','portalThreads','portalMessages',
    'socialAccounts','socialPosts','socialMetrics','campaigns','aiKnowledge','aiRecommendations','featureRequests',
    'voiceQueue','actionQueue','notifications','syncConflicts'
  ];

  function configured() {
    return config.enabled === true &&
      /^https:\/\/[a-z0-9-]+\.supabase\.co$/i.test(String(config.url || '')) &&
      /^sb_publishable_[A-Za-z0-9_-]{20,}$/.test(String(config.publishableKey || '')) &&
      config.productionPromotionAuthorized === false &&
      config.northernLakesEnabled === false &&
      config.externalActionsEnabled === false;
  }

  function esc(value) {
    return String(value == null ? '' : value).replace(/[&<>"']/g, char => ({
      '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
    }[char]));
  }

  function safeMessage(error) {
    return String(error && error.message ? error.message : error || 'Secure sign-in failed.')
      .replace(/Bearer\s+[A-Za-z0-9._-]+/gi, 'Bearer [REDACTED]')
      .slice(0, 700);
  }

  function currentRedirectUrl() {
    return String(config.authRedirectUrl || (location.origin + location.pathname));
  }

  function selectedBusinessKey(userId) {
    return `h38-selected-business:${userId}`;
  }

  function readPreferredBusiness(userId) {
    const queryValue = new URLSearchParams(location.search).get('businessId');
    if (queryValue) return queryValue.trim();
    try { return localStorage.getItem(selectedBusinessKey(userId)) || ''; }
    catch (error) { return ''; }
  }

  function writePreferredBusiness(userId, businessId) {
    try {
      if (businessId) localStorage.setItem(selectedBusinessKey(userId), businessId);
      else localStorage.removeItem(selectedBusinessKey(userId));
    } catch (error) {}
  }

  function initClient() {
    if (runtime.client) return runtime.client;
    if (!configured()) throw new Error('Supabase Auth preview configuration failed closed.');
    if (!window.supabase || typeof window.supabase.createClient !== 'function') {
      throw new Error('Supabase client library did not load.');
    }
    runtime.client = window.supabase.createClient(config.url, config.publishableKey, {
      auth: {
        persistSession: true,
        autoRefreshToken: true,
        detectSessionInUrl: true,
        flowType: 'pkce'
      },
      global: { headers: { 'x-client-info': 'highway-38-business-office-auth-preview' } }
    });
    return runtime.client;
  }

  function rolePermissions(role) {
    if (role === 'owner') return { all: true };
    if (role === 'administrator') return {
      viewCustomers: true, manageWork: true, manageQuotes: true, manageSchedule: true,
      manageCommunications: true, manageField: true, captureEvidence: true, manageInventory: true,
      useInventory: true, manageAssets: true, useAssets: true, manageMaintenance: true,
      manageFinancial: true, viewFinancial: true, manageSocial: true, manageSettings: true, manageUsers: true
    };
    if (role === 'staff') return {
      viewCustomers: true, manageWork: true, viewAssignedWork: true, manageAssignedWork: true,
      manageQuotes: true, manageSchedule: true, manageCommunications: true, manageField: true,
      captureEvidence: true, useInventory: true, useAssets: true
    };
    return { viewCustomers: true, viewAssignedWork: true, viewFinancial: true };
  }

  function enabledModules(membership) {
    return (Array.isArray(membership.modules) ? membership.modules : [])
      .filter(row => row && row.enabled === true)
      .map(row => row.moduleKey)
      .filter(Boolean);
  }

  function buildSnapshot(membership, user, serverTime) {
    const brand = membership.brandConfig && typeof membership.brandConfig === 'object' ? membership.brandConfig : {};
    const moduleConfig = membership.businessModuleConfig && typeof membership.businessModuleConfig === 'object'
      ? membership.businessModuleConfig : {};
    const snapshot = {
      status: 'PASS',
      startupMode: 'SUPABASE_AUTH_FOUNDATION',
      fullRefreshPending: true,
      serverTime: serverTime || new Date().toISOString(),
      version: 'supabase-auth-stage-1',
      schemaVersion: 'business-office-auth-v1',
      authUserId: user.id,
      authorizationStatus: 'active',
      authorizationCheckedAt: new Date().toISOString(),
      user: {
        email: user.email || '',
        userId: user.id,
        displayName: user.user_metadata?.display_name || user.email || 'Business Office user',
        roleId: membership.role,
        roleName: membership.role,
        owner: membership.role === 'owner',
        permissions: rolePermissions(membership.role)
      },
      business: {
        businessId: membership.businessId,
        businessKey: membership.businessKey,
        businessName: membership.businessName,
        status: membership.businessStatus,
        currency: brand.currency || 'USD',
        timeZone: membership.timezone || 'America/Chicago',
        timezone: membership.timezone || 'America/Chicago',
        brandConfig: brand,
        moduleConfig,
        industryPack: brand.industryPack || '',
        industryPacks: Array.isArray(brand.industryPacks) ? brand.industryPacks : []
      },
      modules: enabledModules(membership),
      moduleSettings: Array.isArray(membership.modules) ? membership.modules : [],
      productShells: [],
      safeguards: {
        externalActionsEnabled: false,
        productionMigrationEnabled: false,
        automaticSocialPublishing: false,
        automaticCustomerSending: false,
        automaticFinancialActions: false,
        northernLakesEnabled: false
      }
    };
    EMPTY_COLLECTIONS.forEach(name => { snapshot[name] = []; });
    return snapshot;
  }

  async function setUserScope(userId) {
    if (!window.H38DB || typeof window.H38DB.setUserScope !== 'function') {
      throw new Error('User-scoped offline storage is unavailable.');
    }
    window.H38DB.setUserScope(userId);
  }

  async function writeAuthorization(status, userId, businessId) {
    if (!window.H38DB || typeof window.H38DB.put !== 'function' || !userId) return;
    await window.H38DB.put('meta', {
      id: 'authorization',
      userId,
      businessId: businessId || '',
      status,
      checkedAt: new Date().toISOString()
    });
  }

  function deniedStatus(memberships) {
    if (memberships.some(row => row.membershipStatus === 'suspended' || row.businessStatus === 'suspended')) return 'membership-suspended';
    if (memberships.some(row => row.membershipStatus === 'revoked' || row.businessStatus === 'closed')) return 'membership-revoked';
    if (memberships.some(row => row.membershipStatus === 'invited' || row.businessStatus === 'provisioning')) return 'membership-invited';
    return 'no-membership';
  }

  function browserBusinesses(rows) {
    return rows.map(row => ({
      businessId: row.businessId,
      businessKey: row.businessKey,
      businessName: row.businessName,
      businessStatus: row.businessStatus,
      role: row.role,
      industryPack: row.brandConfig?.industryPack || '',
      industryPacks: Array.isArray(row.brandConfig?.industryPacks) ? row.brandConfig.industryPacks : []
    }));
  }

  function clearBrowserTenantState() {
    runtime.memberships = [];
    runtime.activeMemberships = [];
    runtime.selectedMembership = null;
    if (window.H38DB && typeof window.H38DB.clearUserScope === 'function') window.H38DB.clearUserScope();
    window.dispatchEvent(new CustomEvent('h38:auth-cleared'));
    const signOut = document.getElementById('authSignOutButton');
    if (signOut) signOut.hidden = true;
  }

  function showNotice(message, bad) {
    const node = document.getElementById('h38AuthNotice');
    if (!node) return;
    node.textContent = message;
    node.className = `notice${bad ? ' warn' : ''}`;
  }

  function authPanelRendered(mode) {
    window.dispatchEvent(new CustomEvent('h38:auth-panel-rendered', { detail: { mode } }));
  }

  function installAccessIntentControls(target) {
    const controls = target && typeof target.querySelectorAll === 'function'
      ? target.querySelectorAll('[data-h38-access-intent]')
      : [];
    const copy = {
      office: {
        label: 'Owner or administrator',
        title: 'Sign in to manage your Office',
        help: 'Use the account connected to your active owner or administrator membership.'
      },
      'site-manager': {
        label: 'Site manager / foreman',
        title: 'Sign in for site operations',
        help: 'Use the exact email your owner or administrator added for assigned site and crew work.'
      },
      employee: {
        label: 'Employee',
        title: 'Sign in for assigned work',
        help: 'Use the exact email your employer added for tasks, time, schedule, and field updates.'
      }
    };
    const choose = intent => {
      const selected = copy[intent] || copy.office;
      controls.forEach(control => {
        const active = control.dataset.h38AccessIntent === intent;
        control.classList.toggle('is-active', active);
        control.setAttribute('aria-pressed', String(active));
      });
      const audience = document.getElementById('h38AuthAudience');
      const title = document.getElementById('h38AuthTitle');
      const help = document.getElementById('h38AuthRoleHelp');
      if (audience) audience.textContent = selected.label;
      if (title) title.textContent = selected.title;
      if (help) help.textContent = selected.help;
      document.getElementById('h38AuthEmail')?.focus?.({ preventScroll: true });
    };
    controls.forEach(control => {
      control.addEventListener('click', () => choose(control.dataset.h38AccessIntent || 'office'));
    });
  }

  function authPanel(mode, detail) {
    const target = document.getElementById('mainContent');
    if (!target) return;
    const states = {
      'membership-suspended': ['Access suspended', 'This account is signed in, but its Business Office membership is suspended. A cached business cannot override this result.'],
      'membership-revoked': ['Access removed', 'This account no longer has an active Business Office membership. A direct link or saved business cannot reopen it.'],
      'membership-invited': ['Invitation is not active yet', 'The signed-in email has a pending or provisioning membership that is not allowed to open business data yet.'],
      'no-membership': ['No Business Office membership', 'This signed-in account is not assigned to an active business.'],
      'auth-expired': ['Session expired', 'Sign in again to reopen the Business Office securely.']
    };
    if (mode === 'recovery') {
      target.innerHTML = `<section class="welcome h38-recovery-card"><p class="h38-access-kicker">Business Office secure access</p><h1>Set a new password</h1><p>Choose a new password for this Supabase Auth account.</p><form id="h38RecoveryForm" class="auth-form"><label><span>New password</span><input id="h38NewPassword" type="password" autocomplete="new-password" minlength="10" required></label><button class="primary" type="submit">Save new password</button></form><div id="h38AuthNotice" class="notice">Passwords go directly to Supabase Auth and are never stored in this page.</div></section>`;
      document.getElementById('h38RecoveryForm').onsubmit = async event => {
        event.preventDefault();
        try {
          const password = String(document.getElementById('h38NewPassword').value || '');
          if (password.length < 10) throw new Error('Use at least 10 characters.');
          const { error } = await initClient().auth.updateUser({ password });
          if (error) throw error;
          runtime.recovery = false;
          showNotice('Password updated. Opening the Business Office…', false);
          runtime.bridge?.connect();
        } catch (error) { showNotice(safeMessage(error), true); }
      };
      authPanelRendered(mode);
      return;
    }
    if (states[mode]) {
      const [title, text] = states[mode];
      target.innerHTML = `<section class="welcome h38-recovery-card"><p class="h38-access-kicker">Business Office secure access</p><h1>${esc(title)}</h1><p>${esc(detail || text)}</p><div class="welcome-actions"><button id="h38SignOutDenied" class="primary" type="button">Sign out</button><a class="secondary" href="../customer-portal.html">Customer login</a></div><div id="h38AuthNotice" class="notice">Nothing is sent, approved, purchased, paid, published, or executed automatically.</div></section>`;
      document.getElementById('h38SignOutDenied').onclick = () => signOut();
      authPanelRendered(mode);
      return;
    }
    target.innerHTML = `<section class="welcome h38-access-gate"><div class="h38-access-intro"><p class="h38-access-kicker">Business Office secure access</p><h1>One Office. The right workspace for every role.</h1><p>${esc(detail || 'Owners, administrators, site managers, foremen, and employees use the same secure Office sign-in.')}</p><div class="h38-access-options" aria-label="Choose sign-in guidance"><button class="h38-access-option is-active" type="button" data-h38-access-intent="office" aria-pressed="true"><span class="h38-access-icon" aria-hidden="true">⌂</span><span><strong>Owner or administrator</strong><small>Business controls, team access, and approvals</small></span></button><button class="h38-access-option" type="button" data-h38-access-intent="site-manager" aria-pressed="false"><span class="h38-access-icon" aria-hidden="true">▦</span><span><strong>Site manager / foreman</strong><small>Authorized site, schedule, and crew work</small></span></button><button class="h38-access-option" type="button" data-h38-access-intent="employee" aria-pressed="false"><span class="h38-access-icon" aria-hidden="true">✓</span><span><strong>Employee</strong><small>Assigned tasks, time, and field updates</small></span></button><a class="h38-access-option h38-customer-access" href="../customer-portal.html"><span class="h38-access-icon" aria-hidden="true">◎</span><span><strong>Customer</strong><small>Projects, quotes, invoices, files, and messages</small></span><span aria-hidden="true">→</span></a></div><p class="h38-access-boundary"><strong>Your choice does not grant a role.</strong> Supabase Auth, active business membership, and Row Level Security decide exactly what opens.</p></div><div class="h38-auth-card"><p id="h38AuthAudience" class="h38-auth-audience">Owner or administrator</p><h2 id="h38AuthTitle">Sign in to manage your Office</h2><p id="h38AuthRoleHelp" class="muted">Use the account connected to your active owner or administrator membership.</p><form id="h38AuthForm" class="auth-form"><label><span>Email address</span><input id="h38AuthEmail" type="email" autocomplete="email" inputmode="email" autocapitalize="none" spellcheck="false" required></label><label><span>Password</span><input id="h38AuthPassword" type="password" autocomplete="current-password" required></label><div class="welcome-actions"><button class="primary" type="submit">Sign in securely</button><button id="h38ResetPassword" class="secondary" type="button">Reset password</button></div></form><div id="h38AuthNotice" class="notice">Secure sign-in and access rules determine access. Saved links and selected sign-in guidance never grant permission.</div></div></section>`;
    installAccessIntentControls(target);
    document.getElementById('h38AuthForm').onsubmit = async event => {
      event.preventDefault();
      try {
        const email = String(document.getElementById('h38AuthEmail').value || '').trim().toLowerCase();
        const password = String(document.getElementById('h38AuthPassword').value || '');
        showNotice('Signing in securely…', false);
        const { data, error } = await initClient().auth.signInWithPassword({ email, password });
        if (error) throw error;
        if (!data.session) throw new Error('Supabase Auth did not create a session.');
        document.getElementById('h38AuthPassword').value = '';
        await runtime.bridge?.connect();
      } catch (error) { showNotice(safeMessage(error), true); }
    };
    document.getElementById('h38ResetPassword').onclick = async () => {
      try {
        const email = String(document.getElementById('h38AuthEmail').value || '').trim().toLowerCase();
        if (!email) throw new Error('Enter the email address first.');
        const { error } = await initClient().auth.resetPasswordForEmail(email, { redirectTo: currentRedirectUrl() });
        if (error) throw error;
        showNotice('Check your email for the password reset link. The page does not confirm whether an address is registered.', false);
      } catch (error) { showNotice(safeMessage(error), true); }
    };
    authPanelRendered(mode || 'signin');
  }

  async function signOut() {
    try {
      if (runtime.client) await runtime.client.auth.signOut();
    } finally {
      runtime.session = null;
      runtime.user = null;
      clearBrowserTenantState();
      runtime.bridge?.onStatus('sign-in-required');
      authPanel('signin', 'Signed out.');
    }
  }

  class SupabaseBusinessOfficeBridge {
    constructor(frame, url, onStatus, onBootstrap, onFullSnapshot, onError) {
      this.frame = frame;
      this.url = url;
      this.onStatus = onStatus || (() => {});
      this.onBootstrap = onBootstrap || (() => {});
      this.onFullSnapshot = onFullSnapshot || (() => {});
      this.onError = onError || (() => {});
      this.ready = false;
      this.transport = 'supabase-auth';
      runtime.bridge = this;
    }

    setUrl(url) { this.url = url; }
    authorize() { this.onStatus('sign-in-required'); authPanel('signin'); return true; }

    async connect() {
      try {
        const client = initClient();
        if (!runtime.subscription) {
          const listener = client.auth.onAuthStateChange((event, session) => {
            if (event === 'PASSWORD_RECOVERY') {
              runtime.recovery = true;
              authPanel('recovery');
              return;
            }
            if (event === 'SIGNED_OUT') {
              runtime.session = null;
              runtime.user = null;
              this.ready = false;
              clearBrowserTenantState();
              this.onStatus('sign-in-required');
              return;
            }
            if (session && (!runtime.session || runtime.session.access_token !== session.access_token)) {
              setTimeout(() => this.connect(), 0);
            }
          });
          runtime.subscription = listener.data.subscription;
        }
        const { data, error } = await client.auth.getSession();
        if (error) throw error;
        const session = data.session;
        if (!session || !session.user) {
          this.ready = false;
          runtime.session = null;
          runtime.user = null;
          clearBrowserTenantState();
          this.onStatus('sign-in-required');
          return;
        }
        runtime.session = session;
        runtime.user = session.user;
        await setUserScope(session.user.id);
        const signOutButton = document.getElementById('authSignOutButton');
        if (signOutButton) {
          signOutButton.hidden = false;
          signOutButton.onclick = () => signOut();
        }
        if (!navigator.onLine) {
          this.ready = false;
          this.onStatus('offline-authenticated');
          return;
        }
        this.onStatus('connected');
        const { data: authState, error: authError } = await client.rpc('business_office_auth_state');
        if (authError) throw authError;
        if (!authState || authState.status !== 'PASS') throw new Error('Business membership resolution failed closed.');
        runtime.memberships = Array.isArray(authState.memberships) ? authState.memberships : [];
        runtime.activeMemberships = runtime.memberships.filter(row => row.membershipStatus === 'active' && row.businessStatus === 'active');
        if (!runtime.activeMemberships.length) {
          const status = deniedStatus(runtime.memberships);
          await writeAuthorization(status, session.user.id, '');
          writePreferredBusiness(session.user.id, '');
          this.ready = false;
          this.onStatus(status);
          return;
        }
        const requestedKey = String(new URLSearchParams(location.search).get('businessKey') || '').trim().toLowerCase();
        const preferred = readPreferredBusiness(session.user.id);
        // A branded entry is a selection hint, never authorization. Resolve it only
        // against active server memberships, before any saved-business snapshot paints.
        let selected = requestedKey
          ? runtime.activeMemberships.find(row => String(row.businessKey || '').toLowerCase() === requestedKey) || null
          : runtime.activeMemberships.find(row => row.businessId === preferred) || null;
        if (requestedKey && !selected) {
          runtime.selectedMembership = null;
          await writeAuthorization('no-membership', session.user.id, '');
          this.ready = false;
          this.onStatus('no-membership');
          return;
        }
        if (!selected && runtime.activeMemberships.length === 1) selected = runtime.activeMemberships[0];
        runtime.selectedMembership = selected;
        if (selected) {
          writePreferredBusiness(session.user.id, selected.businessId);
          await writeAuthorization('active', session.user.id, selected.businessId);
        }
        this.ready = true;
        const startup = {
          status: 'PASS',
          authTransport: 'supabase-auth',
          user: { id: session.user.id, email: session.user.email || '' },
          canSwitchBusinesses: runtime.activeMemberships.length > 1,
          businesses: browserBusinesses(runtime.activeMemberships),
          selectedBusinessId: selected ? selected.businessId : '',
          snapshot: selected ? buildSnapshot(selected, session.user, authState.serverTime) : null,
          safeguards: authState.safeguards || {}
        };
        this.onBootstrap(startup);
        this.onStatus('bootstrapped');
      } catch (error) {
        this.ready = false;
        const message = safeMessage(error);
        this.onError('authorization', message);
      }
    }

    async request(action, args) {
      if (!runtime.session || !runtime.user) {
        const error = new Error('Supabase Auth session is required.');
        error.code = 'AUTH_REQUIRED';
        throw error;
      }
      if (!navigator.onLine) throw new Error('Offline mode cannot refresh authorization.');
      if (action === 'listBusinesses') return browserBusinesses(runtime.activeMemberships);
      if (action === 'acceptanceStatus') return {
        status: 'PASS', acceptance: 'SUPABASE_AUTH_ACTIVE_BUSINESS', readOnly: true,
        activeBusinessCount: runtime.activeMemberships.length, externalActionsEnabled: false,
        productionPromotionAuthorized: false, northernLakesEnabled: false
      };
      if (action === 'fullStartupRefresh' || action === 'completionBootstrap') {
        const businessId = String(args && args.businessId || '');
        const membership = runtime.activeMemberships.find(row => row.businessId === businessId);
        if (!membership) throw new Error('The selected business is not an active membership.');
        runtime.selectedMembership = membership;
        writePreferredBusiness(runtime.user.id, membership.businessId);
        await writeAuthorization('active', runtime.user.id, membership.businessId);
        return buildSnapshot(membership, runtime.user, new Date().toISOString());
      }
      throw new Error(`${action} is not enabled during the Auth-only migration stage. Existing Google production remains the fallback.`);
    }
  }

  window.H38_SUPABASE_AUTH = {
    enabled: configured(),
    render: authPanel,
    signOut,
    foundationSnapshotRequiresHydration: true,
    authFoundationNeverAuthoritative: true,
    getState: () => ({
      userId: runtime.user?.id || '',
      email: runtime.user?.email || '',
      activeBusinessCount: runtime.activeMemberships.length,
      selectedBusinessId: runtime.selectedMembership?.businessId || '',
      recovery: runtime.recovery,
      transport: 'supabase-auth'
    })
  };

  if (configured()) window.H38Bridge = SupabaseBusinessOfficeBridge;
  else window.H38Bridge = LegacyBridge;
})();
;

/* --- ./supabase-invite-activation.js --- */
(function () {
  'use strict';

  const config=window.H38_BUSINESS_OFFICE_SUPABASE || {};
  const auth=window.H38_SUPABASE_AUTH;
  const Bridge=window.H38Bridge;
  if(!auth || auth.enabled!==true || !Bridge || !Bridge.prototype || !window.supabase)return;

  function client(){
    return window.H38_SUPABASE_SHARED_CLIENT?.ensure?.() || window.supabase.createClient(config.url,config.publishableKey,{
      auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true,flowType:'pkce'},
      global:{headers:{'x-client-info':'h38-business-office-invite-activation-client'}}
    });
  }
  function text(value){return String(value==null?'':value);}
  function notice(message,bad){
    const node=document.getElementById('h38AuthNotice');
    if(!node)return;
    node.textContent=message;
    node.className=`notice${bad?' warn':''}`;
  }

  function installActivationControl(){
    const form=document.getElementById('h38AuthForm');
    const emailInput=document.getElementById('h38AuthEmail');
    const actionRow=form?.querySelector('.welcome-actions');
    if(!form || !emailInput || !actionRow || document.getElementById('h38ActivateInvitation'))return;

    const button=document.createElement('button');
    button.id='h38ActivateInvitation';
    button.className='secondary';
    button.type='button';
    button.textContent='Activate invitation';
    actionRow.appendChild(button);

    const explanation=document.createElement('p');
    explanation.className='muted small';
    explanation.textContent='Invited owner, administrator, site manager, foreman, or employee? Enter the exact invited email and request the secure activation email. No password is handled by the business office.';
    form.appendChild(explanation);

    button.onclick=async()=>{
      try{
        const email=text(emailInput.value).trim().toLowerCase();
        if(!email)throw new Error('Enter the invited email address first.');
        button.disabled=true;
        notice('Requesting the secure invitation email…',false);
        const {data,error}=await client().functions.invoke('business-office-invite-activation',{body:{email}});
        if(error)throw error;
        if(!data || data.status!=='PASS')throw new Error(data?.error || 'Invitation request failed.');
        notice(data.message || 'Check the invited email for the secure activation link.',false);
      }catch(error){
        notice(text(error && error.message || error).slice(0,700),true);
      }finally{
        button.disabled=false;
      }
    };
  }

  addEventListener('h38:auth-panel-rendered',installActivationControl);
  addEventListener('DOMContentLoaded',installActivationControl,{once:true});
  installActivationControl();

  window.H38_INVITE_ACTIVATION={
    enabled:true,
    functionName:'business-office-invite-activation',
    passwordHandledByHighway38:false,
    automaticBusinessActivation:false,
    externalCustomerActionsEnabled:false
  };
})();
;

/* --- ./auth-session-guard.js --- */
(function () {
  'use strict';
  const auth = window.H38_SUPABASE_AUTH;
  if (!auth || typeof auth.getState !== 'function') return;
  const readState = auth.getState.bind(auth);
  auth.getState = function () {
    const result = readState() || {};
    const scopedUserId = window.H38DB?.getUserScope?.() || '';
    const activeBusinessCount = Number(result.activeBusinessCount || 0);
    return {
      ...result,
      userId: scopedUserId || result.userId || '',
      selectedBusinessId: scopedUserId && activeBusinessCount > 0 ? String(result.selectedBusinessId || '') : ''
    };
  };
})();
;

/* --- ./supabase-session-recovery.js --- */
(function () {
  'use strict';

  const shared = window.H38_SUPABASE_SHARED_CLIENT;
  const officeAuth = window.H38_SUPABASE_AUTH;
  if (!shared?.enabled || !officeAuth || typeof officeAuth.signOut !== 'function') return;
  if (window.H38_SUPABASE_SESSION_RECOVERY?.enabled) return;

  let checking = false;
  let redirecting = false;
  let lastValidatedAt = 0;
  const h38RecoveryPageLoad = Date.now();

  function text(value) {
    return String(value == null ? '' : value);
  }

  function isSessionFailure(error) {
    const code = text(error && (error.code || error.error_code)).toLowerCase();
    const message = text(error && error.message || error).toLowerCase();
    return code.includes('refresh_token_not_found') ||
      code.includes('bad_jwt') ||
      code.includes('no_authorization') ||
      message.includes('invalid refresh token') ||
      message.includes('refresh token not found') ||
      message.includes('jwt expired') ||
      message.includes('token is malformed') ||
      message.includes('session is invalid') ||
      message.includes('session expired');
  }

  function setStatus(message) {
    const businessStatus = document.getElementById('businessStatus');
    if (businessStatus) businessStatus.textContent = message;
  }

  async function requireSignIn(reason) {
    if (redirecting) return false;
    redirecting = true;
    setStatus('Session expired · secure sign-in required');
    try {
      await officeAuth.signOut();
    } catch (error) {
      try {
        const client = shared.get();
        if (client) await client.auth.signOut({ scope: 'local' });
      } catch (ignore) {}
    }
    window.dispatchEvent(new CustomEvent('h38:session-invalid', {
      detail: { reason: text(reason || 'Supabase session expired.'), draftPreserved: true }
    }));
    return false;
  }

  async function validate(trigger, force) {
    if (checking || redirecting || !navigator.onLine) return true;
    const now = Date.now();
    if (!force && now - lastValidatedAt < 15000) return true;
    checking = true;
    try {
      const client = shared.ensure();
      const sessionResult = await client.auth.getSession();
      if (sessionResult.error) {
        if (isSessionFailure(sessionResult.error)) return requireSignIn(sessionResult.error.message);
        throw sessionResult.error;
      }
      let session = sessionResult.data && sessionResult.data.session;
      if (!session) return true;

      const expiresAtMs = Number(session.expires_at || 0) * 1000;
      if (expiresAtMs && expiresAtMs <= Date.now() + 60000) {
        const refreshed = await client.auth.refreshSession();
        if (refreshed.error || !refreshed.data?.session) {
          return requireSignIn(refreshed.error?.message || 'Supabase session refresh failed.');
        }
        session = refreshed.data.session;
      }

      const userResult = await client.auth.getUser(session.access_token);
      if (userResult.error || !userResult.data?.user) {
        return requireSignIn(userResult.error?.message || 'Supabase session could not be verified.');
      }
      lastValidatedAt = Date.now();
      window.dispatchEvent(new CustomEvent('h38:session-valid', {
        detail: { trigger: text(trigger), userId: userResult.data.user.id, validatedAt: new Date().toISOString() }
      }));
      return true;
    } catch (error) {
      if (isSessionFailure(error)) return requireSignIn(error.message);
      return false;
    } finally {
      checking = false;
    }
  }

  function refreshServiceWorker() {
    if (!('serviceWorker' in navigator) || !navigator.onLine) return;
    const build = '20260807-2132';
    const reloadKey = `h38:worker-reloaded:${build}`;
    navigator.serviceWorker.addEventListener('controllerchange', () => {
      try {
        if (sessionStorage.getItem(reloadKey)) return;
        sessionStorage.setItem(reloadKey, '1');
      } catch (ignore) {}
      // Never yank a working Office back to Today: if business records are
      // already painted, the new worker simply takes over on the next cold
      // start instead of reloading mid-session.
      try { if (typeof state !== 'undefined' && state && state.snapshot) return; } catch (ignore) {}
      if (Date.now() - h38RecoveryPageLoad < 15000) return;
      location.reload();
    });
    navigator.serviceWorker.register(`./service-worker.js?build=${build}`, {
      scope: './',
      updateViaCache: 'none'
    }).then(registration => registration.update()).catch(error => {
      console.warn('Business Office service worker refresh failed', error);
    });
  }

  window.addEventListener('pageshow', () => { void validate('pageshow', true); });
  window.addEventListener('online', () => { void validate('online', true); refreshServiceWorker(); });
  window.addEventListener('load', refreshServiceWorker, { once: true });
  document.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'visible') void validate('visible', false);
  });
  document.addEventListener('click', event => {
    const protectedAction = event.target?.closest?.('#h38AiQuoteDraftButton,#syncButton,#loadBusinessButton');
    if (!protectedAction) return;
    void validate('protected-action', true);
  }, true);

  setTimeout(() => { void validate('startup', true); }, 0);

  window.H38_SUPABASE_SESSION_RECOVERY = Object.freeze({
    enabled: true,
    build: '20260807-2132',
    validate: function () { return validate('manual', true); },
    singleClientRequired: true,
    clearsRevokedMembershipState: true,
    preservesDrafts: true,
    forcesCurrentServiceWorker: true
  });
})();

// Normal Office startup does not need hundreds of Proof/Error rows. Keep those
// durable records in Supabase and load them explicitly for management reports.
// The guard is installed from this live-first runtime before supabase-data.js
// executes, so stale service-worker copies of supabase-data.js cannot reintroduce
// the two hot audit reads.
(function(){
  'use strict';
  if(window.H38_SUPABASE_TRAFFIC_GUARD?.enabled)return;
  const shared=window.H38_SUPABASE_SHARED_CLIENT;
  if(!shared?.enabled)return;
  const api=shared.ensure?.();
  if(!api||typeof api.from!=='function')return;

  const BUILD='20260905-supabase-traffic-efficiency-1';
  const AUDIT_TABLES=new Set(['business_proof_log','business_error_log']);
  const rawFrom=api.from.bind(api);
  let suppressedStartupAuditReads=0;
  let explicitAuditLoads=0;

  function emptyQuery(){
    const response={data:[],error:null,count:null,status:200,statusText:'OK'};
    let proxy;
    proxy=new Proxy({}, {
      get(_target,property){
        if(property==='then')return (resolve,reject)=>Promise.resolve(response).then(resolve,reject);
        if(property==='catch')return reject=>Promise.resolve(response).catch(reject);
        if(property==='finally')return callback=>Promise.resolve(response).finally(callback);
        if(property===Symbol.toStringTag)return 'Promise';
        return ()=>proxy;
      }
    });
    return proxy;
  }

  function isOperationalHydration(){
    try{
      const stack=String(new Error().stack||'');
      return /hydrateSnapshot/.test(stack)&&/supabase-data\.js/.test(stack);
    }catch(_){return false;}
  }

  api.from=function(table){
    const name=String(table||'');
    if(AUDIT_TABLES.has(name)&&isOperationalHydration()){
      suppressedStartupAuditReads+=1;
      return emptyQuery();
    }
    return rawFrom(name);
  };

  function mapProof(row){
    return {
      'Proof ID':row.id,'Action Type':row.action_type,'Entity Type':row.entity_type||'',
      'Entity ID':row.entity_id||'','Result':row.result,'Details':row.details||{},
      'External Action Occurred':row.external_action_occurred===true,'Created Time':row.created_at
    };
  }

  function mapError(row){
    return {
      'Error ID':row.id,'Source':row.source,'Error Code':row.error_code||'',
      'Message':row.message,'Severity':row.severity,'Status':row.status,
      'Context':row.context||{},'Occurrence Count':Number(row.occurrence_count||1),
      'First Seen':row.created_at,'Last Seen':row.last_seen_at||row.created_at,'Created Time':row.created_at
    };
  }

  async function loadAuditHistory(businessId,options={}){
    const id=String(businessId||window.state?.businessId||'').trim();
    if(!id)throw new Error('Choose a business before loading audit history.');
    const proofLimit=Math.max(1,Math.min(Number(options.proofLimit||500),1000));
    const errorLimit=Math.max(1,Math.min(Number(options.errorLimit||250),1000));
    const [proofResult,errorResult]=await Promise.all([
      rawFrom('business_proof_log').select('*').eq('business_id',id).order('created_at',{ascending:false}).limit(proofLimit),
      rawFrom('business_error_log').select('*').eq('business_id',id).order('created_at',{ascending:false}).limit(errorLimit)
    ]);
    if(proofResult.error)throw proofResult.error;
    if(errorResult.error)throw errorResult.error;
    explicitAuditLoads+=1;
    const result={proofLog:(proofResult.data||[]).map(mapProof),errorLog:(errorResult.data||[]).map(mapError)};
    if(window.state?.snapshot&&String(window.state?.businessId||'')===id){
      window.state.snapshot.proofLog=result.proofLog;
      window.state.snapshot.errorLog=result.errorLog;
    }
    window.dispatchEvent(new CustomEvent('h38:audit-history-loaded',{detail:{businessId:id,proofCount:result.proofLog.length,errorCount:result.errorLog.length}}));
    return result;
  }

  window.H38_SUPABASE_TRAFFIC_GUARD=Object.freeze({
    enabled:true,
    build:BUILD,
    startupAuditHistoryLazy:true,
    auditHistoryStillAvailable:true,
    rlsStillAuthoritative:true,
    loadAuditHistory,
    metrics:()=>({suppressedStartupAuditReads,explicitAuditLoads})
  });
})();

